"""Liger KL-divergence raw-op autograd-pair wrapper."""

from __future__ import annotations

from typing import Callable as _Callable
import inspect as _inspect

import torch as _torch
import torch.distributed.tensor as _torch_distributed_tensor  # noqa: F401


__all__ = ["liger_available", "make_liger_kl_div_autograd_pair_fns"]


_LOG_TARGET = False

# Liger's KL forward adds `eps` before log when supplied.  Use the smallest
# normal fp32 value: it is finite for zero targets (so 0 * log(eps) -> 0) but is
# too small to perturb any normal probability generated by the benchmark.
_EPS = _torch.finfo(_torch.float32).tiny


def liger_available() -> bool:
    try:
        from liger_kernel.ops.kl_div import kldiv_backward_triton, kldiv_forward_triton  # noqa: F401

        return True
    except ImportError:
        return False


def _has_parameter(fn, name: str) -> bool:
    try:
        return name in _inspect.signature(fn).parameters
    except (TypeError, ValueError):
        return False


def make_liger_kl_div_autograd_pair_fns() -> tuple[_Callable, _Callable]:
    """Return raw-Liger-backed (forward_with_saved, backward_from_saved) for KLDiv batchmean.

    Contract:
        forward_with_saved(y_pred, y_true) -> (loss, saved_tensors)
        backward_from_saved(dloss, saved_tensors) -> d_input

    saved_tensors is a flat tensor-only tuple.
    """
    from liger_kernel.ops.kl_div import kldiv_backward_triton, kldiv_forward_triton

    _forward_accepts_eps = _has_parameter(kldiv_forward_triton, "eps")
    _backward_accepts_in_place = _has_parameter(kldiv_backward_triton, "in_place")
    _backward_accepts_inplace = _has_parameter(kldiv_backward_triton, "inplace")

    def forward_with_saved(y_pred: _torch.Tensor, y_true: _torch.Tensor):
        y_pred = y_pred.contiguous()
        y_true = y_true.contiguous()

        forward_kwargs = {
            "log_target": _LOG_TARGET,
            "reduction": "batchmean",
        }
        if _forward_accepts_eps:
            forward_kwargs["eps"] = _EPS

        loss = kldiv_forward_triton(y_pred, y_true, **forward_kwargs)

        return loss.to(dtype=y_pred.dtype), (y_true,)

    def backward_from_saved(dloss: _torch.Tensor, saved_tensors):
        (y_true,) = saved_tensors

        dloss_work = dloss.contiguous().clone()
        d_input = _torch.empty_like(y_true)

        backward_kwargs = {
            "log_target": _LOG_TARGET,
        }
        if _backward_accepts_in_place:
            backward_kwargs["in_place"] = False
        if _backward_accepts_inplace:
            backward_kwargs["inplace"] = False

        d_input = kldiv_backward_triton(
            y_true,
            dloss_work,
            d_input,
            **backward_kwargs,
        )

        d_input = d_input / y_true.shape[0]
        return d_input.to(dtype=y_true.dtype)

    return forward_with_saved, backward_from_saved
